#' Print an \code{lesreg} Object
#'
#' @description
#' Print an object generated by \code{lesreg}.
#'
#' @param x an object returned from \code{\link{lesreg}}, representing the fitted model.
#' @param ... additional arguments passed to printing methods.
#'
#' @seealso
#' \code{\link{lesreg}}
#'
#' @export
#'
print.lesreg <- function(x, ...){
  if(!is.null(cl <- x$call)){
    cat("Call:\n")
    dput(cl)
  }
  cat("\nQuantile regression coefficients:\n")
  print(x$beta.hat, ...)
  cat("\nExpected shortfall regression coefficients:\n")
  print(x$coefficients, ...)
  nobs <- length(stats::residuals(x))
  rdf <- x$df.residual
  cat("\nDegrees of freedom:", nobs, "total;", rdf, "residual\n")
  if(!is.null(na.action <- x$na.action)){
    cat("  (", stats::naprint(na.action), ")\n", sep = "")
  }
  invisible(x)
}
